export type CatalogLinkProps = {
  heading: string;
  text: string;
  button: { label: string; target: string };
};

export default function CatalogLink({ heading, text, button }: CatalogLinkProps) {
  return (
    <section className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="flex flex-col gap-6 border-t-2 border-border pt-10 md:flex-row md:items-center md:justify-between md:gap-10">
          <div className="min-w-0 max-w-text">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{heading}</h2>
            <p className="mt-3 text-lead text-pretty text-muted-foreground">{text}</p>
          </div>
          <a
            href={button.target}
            className="inline-flex min-h-11 shrink-0 items-center justify-center rounded-control bg-primary px-7 text-center text-body font-bold text-primary-foreground transition-transform duration-200 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            {button.label}
          </a>
        </div>
      </div>
    </section>
  );
}

