// Steps «how booking works»: airy section — heading and lead on the left, three steps laid out on an asymmetric
// grid; each step's big numeral is drawn in code with font-display and a primary rule, no external icons. On phones
// the steps stack into a vertical list. Own composition, calm rise entrance only.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type BookingStepsProps = {
  heading: string;
  text?: string;
  steps: Step[];
};

export default function BookingSteps({ heading, text, steps }: BookingStepsProps) {
  const still = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-x-8 gap-y-10 md:grid-cols-12">
          <div className="min-w-0 md:col-span-4">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
            {text ? (
              <p className="mt-5 max-w-text text-lead text-pretty text-muted-foreground">{text}</p>
            ) : null}
          </div>
          <ol className="grid min-w-0 gap-10 sm:grid-cols-3 sm:gap-6 md:col-span-8 md:gap-8">
            {steps.map((step, i) => (
              <m.li
                key={step.title}
                initial={still ? false : { opacity: 0, y: 24 }}
                whileInView={still ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.3 }}
                transition={{ duration: 0.5, ease: "easeOut", delay: still ? 0 : i * 0.12 }}
                className="group min-w-0"
              >
                {/* Numeral drawn in code: big display figure over a short primary rule */}
                <p
                  aria-hidden="true"
                  className="font-display text-hero font-bold leading-none text-primary/25 select-none"
                >
                  {String(i + 1)}
                </p>
                <div className="mt-4 h-[3px] w-10 rounded-sm bg-primary transition-transform duration-300 ease-out group-hover:scale-x-150" />
                <h3 className="mt-5 font-display text-h3 font-bold text-balance wrap-break-word">
                  <span className="sr-only">Шаг {i + 1}. </span>
                  {step.title}
                </h3>
                <p className="mt-3 max-w-text text-body text-pretty text-muted-foreground">{step.text}</p>
              </m.li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  );
}

