// Своё движение — rise на входе, calm; без фото в props — без блока фото.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Item = {
  title: string;
  text: string;
};

export type BookingConfirmationProps = {
  heading: string;
  items: Item[];
};

export default function BookingConfirmation({ heading, items }: BookingConfirmationProps) {
  const reduce = useReducedMotion();

  return (
    <section className="bg-inverse font-sans text-inverse-foreground">
      <LazyMotion features={domAnimation}>
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-x-12 gap-y-10 lg:grid-cols-12 lg:gap-y-0">
            <m.div
              initial={reduce ? false : { opacity: 0, y: 24 }}
              whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              className="lg:col-span-6 lg:pr-8"
            >
              <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
            </m.div>
            {items.length > 0 ? (
              <ul className="min-w-0 lg:col-span-6 lg:border-l lg:border-inverse-foreground/25 lg:pl-12">
                {items.map((item, i) => (
                  <m.li
                    key={item.title}
                    initial={reduce ? false : { opacity: 0, y: 16 }}
                    whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                    viewport={{ once: true, margin: "-80px" }}
                    transition={{ duration: 0.45, ease: "easeOut", delay: reduce ? 0 : 0.08 * (i + 1) }}
                    className={
                      i > 0
                        ? "border-t border-inverse-foreground/25 py-6 first:pt-0 last:pb-0"
                        : "pb-6"
                    }
                  >
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{item.title}</h3>
                    <p className="mt-2 max-w-text text-body text-pretty text-inverse-foreground/80">{item.text}</p>
                  </m.li>
                ))}
              </ul>
            ) : null}
          </div>
        </div>
      </LazyMotion>
    </section>
  );
}

